const test = require('node:test');
const assert = require('node:assert');
const http = require('node:http');
const { upload, checkSize, MAX_BYTES } = require('../upload');

test('refuses files over 5 MB', () => {
  assert.throws(() => checkSize(Buffer.alloc(MAX_BYTES + 1)), /too large/);
});

test('uploads a small file and returns its id', async (t) => {
  let received;
  const server = http.createServer((req, res) => {
    const chunks = [];
    req.on('data', (c) => chunks.push(c));
    req.on('end', () => {
      received = { method: req.method, url: req.url, body: Buffer.concat(chunks).toString() };
      res.setHeader('content-type', 'application/json');
      res.end(JSON.stringify({ id: 'abc123' }));
    });
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  t.after(() => server.close());
  const url = `http://127.0.0.1:${server.address().port}/upload`;

  const id = await upload('a.txt', Buffer.from('hello'), url);
  assert.match(id, /^[a-z0-9]+$/);
  assert.deepStrictEqual(received, { method: 'POST', url: '/upload?name=a.txt', body: 'hello' });
});
EOF
npm test 2>&1 | grep -E "^(not )?ok|^# (pass|fail)"

